INSERT IGNORE INTO `#__j2commerce_emailtemplates` (`j2commerce_emailtemplate_id`, `email_type`, `receiver_type`, `orderstatus_id`, `group_id`, `paymentmethod`, `subject`, `body`, `body_json`, `body_source`, `body_source_file`, `custom_css`, `language`, `enabled`, `ordering`) VALUES (1,'transactional','customer','1','*','*','[LANG:COM_J2COMMERCE_EMAIL_THANKS_FOR_YOUR_ORDER]','<!-- J2Commerce Order Confirmed — Modern Template -->\n<style>\n  @media only screen and (max-width: 620px) {\n    .email-container { width: 100% !important;background-color: #ffffff !important;}\n    .mobile-padding { padding-left: 20px !important; padding-right: 20px !important; }\n    .mobile-full { width: 100% !important; display: block !important; }\n    .mobile-hide { display: none !important; }\n    .mobile-stack { display: block !important; width: 100% !important; }\n    .tracker-step { padding: 0 4px !important; font-size: 10px !important; }\n    .address-col { display: block !important; width: 100% !important; padding: 0 0 16px 0 !important; }\n  }\n</style>\n\n<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: [EMAIL_BG_COLOR]; font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 30px 10px;">\n      <table class="email-container" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%;background-color:#fff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td style="padding: 20px 30px; background-color: #ffffff; border-radius: 12px 12px 0 0; text-align: center;">\n            [IF:STORE_LOGO_URL]\n            <a href="[SITEURL]" target="_blank">\n                <img src="[STORE_LOGO_URL]" alt="[SITENAME]" style="display: block; border: 0;height: [LOGO_MAX_HEIGHT]px; width:auto;" />\n            </a>\n            [/IF:STORE_LOGO_URL]\n            [IFNOT:STORE_LOGO_URL]\n            <a href="[SITEURL]" target="_blank" style="font-size: 22px; font-weight: bold; color: [ACCENT_COLOR]; text-decoration: none;">[SITENAME]</a>\n            [/IFNOT:STORE_LOGO_URL]\n          </td>\n        </tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:AFTER_HEADER]</td></tr>\n\n        <!-- Success Banner -->\n        <tr>\n          <td style="background-color: #059669; padding: 32px 30px; text-align: center;">\n            <!-- Checkmark Circle -->\n            <table cellpadding="0" cellspacing="0" border="0" align="center">\n              <tr>\n                <td style="width: 56px; height: 56px; background-color: rgba(255,255,255,0.2); border-radius: 50%; text-align: center; vertical-align: middle; font-size: 28px; color: #ffffff;">\n                  &#10003;\n                </td>\n              </tr>\n            </table>\n            <h1 style="margin: 16px 0 6px 0; font-size: 26px; font-weight: bold; color: #ffffff;">[LANG:COM_J2COMMERCE_EMAIL_ORDER_CONFIRMED_2]</h1>\n            <p style="margin: 0; font-size: 15px; color: #d1fae5;">\n              [LANG:COM_J2COMMERCE_EMAIL_THANK_YOU_YOUR_ORDER_CONFIRMED]\n            </p>\n          </td>\n        </tr>\n\n        <!-- Status Tracker -->\n        <tr>\n          <td style="background-color: #ffffff; padding: 24px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0">\n              <tr>\n                <!-- Step 1: Ordered (Active) -->\n                <td class="tracker-step" style="width: 33%; text-align: center; padding: 0 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td align="center">\n                        <table cellpadding="0" cellspacing="0" border="0">\n                          <tr>\n                            <td style="width: 32px; height: 32px; background-color: #059669; border-radius: 50%; text-align: center; vertical-align: middle; color: #ffffff; font-size: 14px; font-weight: bold;">&#10003;</td>\n                          </tr>\n                        </table>\n                      </td>\n                    </tr>\n                    <tr>\n                      <td style="padding-top: 6px; font-size: 11px; font-weight: bold; color: #059669; text-align: center;">[LANG:COM_J2COMMERCE_EMAIL_ORDERED]</td>\n                    </tr>\n                  </table>\n                </td>\n                <!-- Step 2: Processing (Pending) -->\n                <td class="tracker-step" style="width: 33%; text-align: center; padding: 0 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td align="center">\n                        <table cellpadding="0" cellspacing="0" border="0">\n                          <tr>\n                            <td style="width: 32px; height: 32px; background-color: #e5e7eb; border-radius: 50%; text-align: center; vertical-align: middle; color: #9ca3af; font-size: 14px; font-weight: bold;">2</td>\n                          </tr>\n                        </table>\n                      </td>\n                    </tr>\n                    <tr>\n                      <td style="padding-top: 6px; font-size: 11px; color: #9ca3af; text-align: center;">[LANG:COM_J2COMMERCE_EMAIL_PROCESSING]</td>\n                    </tr>\n                  </table>\n                </td>\n                <!-- Step 3: Shipped (Pending) -->\n                <td class="tracker-step" style="width: 34%; text-align: center; padding: 0 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td align="center">\n                        <table cellpadding="0" cellspacing="0" border="0">\n                          <tr>\n                            <td style="width: 32px; height: 32px; background-color: #e5e7eb; border-radius: 50%; text-align: center; vertical-align: middle; color: #9ca3af; font-size: 14px; font-weight: bold;">3</td>\n                          </tr>\n                        </table>\n                      </td>\n                    </tr>\n                    <tr>\n                      <td style="padding-top: 6px; font-size: 11px; color: #9ca3af; text-align: center;">[LANG:COM_J2COMMERCE_EMAIL_SHIPPED]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n              <!-- Progress Bar -->\n              <tr>\n                <td colspan="3" style="padding: 12px 8px 0 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #e5e7eb; border-radius: 4px; height: 4px;">\n                    <tr>\n                      <td style="width: 33%; background-color: #059669; border-radius: 4px; height: 4px;"></td>\n                      <td style="width: 67%; height: 4px;"></td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Order Details Summary -->\n        <tr>\n          <td style="padding: 0 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f0fdf4; border-radius: 8px; margin-bottom: 4px;">\n              <tr>\n                <td style="padding: 14px 20px; font-size: 13px; color: #374151;">\n                  <strong>[LANG:COM_J2COMMERCE_EMAIL_ORDER]</strong>[LANG:COM_J2COMMERCE_EMAIL_INVOICE]\n                  <br>[IF:ORDER_TOKEN]<span style="font-size: 12px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_ORDER_TOKEN_2]</span>[/IF:ORDER_TOKEN]\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:BEFORE_ITEMS]</td></tr>\n\n        <!-- Order Items Card -->\n        <tr>\n          <td class="mobile-padding" styl