le="font-size: 12px; color: #9ca3af;">[LANG:COM_J2COMMERCE_EMAIL_SKU_2]</span>[/IF:ITEM_SKU]\n                  [IF:ITEM_OPTIONS]<br /><span style="font-size: 12px; color: #6b7280;">[ITEM_OPTIONS]</span>[/IF:ITEM_OPTIONS]\n                  <br /><span style="font-size: 12px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_EACH]</span>\n                  [ITEM_ANNOTATIONS]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; text-align: center; vertical-align: top; font-size: 14px; color: [TEXT_COLOR];">[ITEM_QTY]</td>\n                <td style="padding: 12px 20px; border-top: 1px solid #f3f4f6; text-align: right; vertical-align: top; font-size: 14px; font-weight: 600; color: [TEXT_COLOR];">[ITEM_TOTAL]</td>\n              </tr>\n              <!--[/ITEMS_LOOP]-->\n              <!-- Totals -->\n              <tr>\n                <td colspan="4" style="padding: 0;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f9fafb; border-top: 1px solid #e5e7eb;">\n                    <tr>\n                      <td style="padding: 10px 20px 2px 20px; font-size: 13px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_SUBTOTAL]</td>\n                      <td style="padding: 10px 20px 2px 20px; font-size: 13px; color: #6b7280; text-align: right;">[SUBTOTAL]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 6px 20px; font-size: 13px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_SHIPPING]</td>\n                      <td style="padding: 6px 20px; font-size: 13px; color: #6b7280; text-align: right;">[IF:SHIPPING_METHOD][SHIPPING_AMOUNT][/IF:SHIPPING_METHOD]</td>\n                    </tr>\n                    <tr>\n                      <td colspan="2" style="padding: 0;">[DISCOUNT_LINES]</td>\n                    </tr>\n                    <tr>\n                      <td colspan="2" style="padding: 0;">[TAX_LINES]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 20px; font-size: 16px; font-weight: bold; color: [TEXT_COLOR]; border-top: 2px solid #e5e7eb;">[LANG:COM_J2COMMERCE_EMAIL_TOTAL]</td>\n                      <td style="padding: 14px 20px; font-size: 16px; font-weight: bold; color: [TEXT_COLOR]; text-align: right; border-top: 2px solid #e5e7eb;">[ORDERAMOUNT]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:AFTER_ITEMS]</td></tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:BEFORE_SHIPPING]</td></tr>\n\n        <!-- Shipping & Billing Cards -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0">\n              <tr>\n                <!-- Billing -->\n                <td class="address-col" style="width: 50%; vertical-align: top; padding-right: 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_BILLING_ADDRESS]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 14px; color: [TEXT_COLOR]; line-height: 1.6;">\n                        <strong>[BILLING_FIRSTNAME] [BILLING_LASTNAME]</strong>[IF:BILLING_COMPANY]<br />[BILLING_COMPANY][/IF:BILLING_COMPANY]<br />\n                        [BILLING_ADDRESS_1][IF:BILLING_ADDRESS_2]<br />[BILLING_ADDRESS_2][/IF:BILLING_ADDRESS_2]<br />\n                        [BILLING_CITY], [BILLING_STATE] [BILLING_ZIP]<br />\n                        [BILLING_COUNTRY][IF:BILLING_PHONE]<br />[BILLING_PHONE][/IF:BILLING_PHONE]\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n                <!-- Shipping -->\n                <td class="address-col" style="width: 50%; vertical-align: top; padding-left: 8px;">\n                  [IF:SHIPPING_FIRSTNAME]\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_SHIPPING_ADDRESS]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 14px; color: [TEXT_COLOR]; line-height: 1.6;">\n                        <strong>[SHIPPING_FIRSTNAME] [SHIPPING_LASTNAME]</strong><br />\n                        [SHIPPING_ADDRESS_1][IF:SHIPPING_ADDRESS_2]<br />[SHIPPING_ADDRESS_2][/IF:SHIPPING_ADDRESS_2]<br />\n                        [SHIPPING_CITY], [SHIPPING_STATE] [SHIPPING_ZIP]<br />\n                        [SHIPPING_COUNTRY]\n                      </td>\n                    </tr>\n                  </table>\n                  [/IF:SHIPPING_FIRSTNAME]\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Payment Info Card -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n              <tr>\n                <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_PAYMENT_INFORMATION]</td>\n              </tr>\n              <tr>\n                <td style="padding: 14px 18px; font-size: 14px; color: [TEXT_COLOR];">\n                  <strong>[LANG:COM_J2COMMERCE_EMAIL_METHOD]:</strong> [PAYMENT_TYPE]\n                  [IF:SHIPPING_TRACKING_ID]<br /><strong>[LANG:COM_J2COMMERCE_EMAIL_TRACKING_ID_2]:</strong> [SHIPPING_TRACKING_ID][/IF:SHIPPING_TRACKING_ID]\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:AFTER_PAYMENT]</td></tr>\n\n        <!-- Customer Note -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0;">\n            [IF:CUSTOMER_NOTE]\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin: 0; padding: 0;">\n              <tr>\n                <td style="padding: 0 20px 16px 20px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 13px; font-weight: bold; color: #92400e;">[LANG:COM_J2COMMERCE_EMAIL_YOUR_NOTE]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 0 18px 14px 18px; font-size: 14px; color: #78350f; line-height: 1.5;">[CUSTOMER_NOTE]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n            [/IF:CUSTOMER_NOTE]\n          </td>\n        </tr>\n\n        <!-- View Order Button -->\n        <tr>\n          <td style="padding: 10px 20px 24px 20px; text-align: center;">\n            <table cellpadding="0" cellspacing="0" border="0" align="center">\n              <tr>\n                <td style="background-color: [ACCENT_COLOR]; border-radius: 8px; text-align: center;">\n                  <a href="[INVOICE_URL]" style="display: inline-block; padding: 14px 36px; color: #ffffff; text-decoration: none; font-size: 15px; font-weight: bold; letter-spacing: 0.3px;">[LANG:COM_J2COMMERCE_EMAIL_VIEW_YOUR_ORDER]</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Support Block -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 20px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f9fafb; border-radius: 10px;">\n              <tr>\n                <td style="padding: 18px 20px; text-align: center; font-size: 13px; color: #6b7280; line-height: 1.6;">\n                  <strong style="color: [TEXT_COLOR];">[LANG:COM_J2COMMERCE_EMAIL_NEED_HELP]</strong><br />\n                  [LANG:COM_J2COMMERCE_EMAIL_IF_YOU_HAVE_ANY_QUESTIONS_ABOUT_ORDER_RE]\n                  <a href="mailto:[BILLING_EMAIL]" style="color: [ACCENT_COLOR]; text-decoration: none;">[SITENAME]</a>.\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <tr><td style="padding:0;border:0;font-size:0;line-height:0;height:0;overflow:hidden;">[HOOK:BEFORE_FOOTER]</td></tr>\n\n        <!-- Footer -->\n        <tr>\n          <td style="padding: 24px 40px; background-color: #ffffff; border-radius: 0 0 12px 12px; border-top: 1px solid #f3f4f6; text-align: center;">\n            <!-- Social Links -->\n            <table cellpadding="0" cellspacing="0" border="0" align="center" style="margin-bottom: 14px;">\n              <tr>\n                <td style="padding: 0 8px;">[IF:SOCIAL_FACEBOOK]<a href="[SOCIAL_FACEBOOK]" style="display: inline-block; width: 32px; height: 32px; background-color: #e5e7eb; border-radius: 50%; text-align: center; line-height: 32px; text-decoration: none; font-size: 14px; color: #6b7280;">f</a>[/IF:SOCIAL_FACEBOOK]</td>\n                <td style="padding: 0 8px;">[IF:SOCIAL_TWITTER]<a href="[SOCIAL_TWITTER]" style="display: inline-block; width: 32px; height: 32px; background-color: #e5e7eb; border-radius: 50%; text-align: center; line-height: 32px; text-decoration: none; font-size: 14px; color: #6b7280;">&#120143;</a>[/IF:SOCIAL_TWITTER]</td>\n                <td style="padding: 0 8px;">[IF:SOCIAL_INSTAGRAM]<a href="[SOCIAL_INSTAGRAM]" style="display: inline-block; width: 32px; height: 32px; background-color: #e5e7eb; border-radius: 50%; text-align: center; line-height: 32px; text-decoration: none; font-size: 14px; color: #6b7280;">&#9741;</a>[/IF:SOCIAL_INSTAGRAM]</td>\n              </tr>\n            </table>\n            <p style="font-size: 12px; color: #9ca3af; margin: 0; line-height: 1.6;">[FOOTER_TEXT]</p>\n            <p style="font-size: 12px; color: #9ca3af; margin: 8px 0 0 0;">\n              &copy; [CURRENT_YEAR] <a href="[SITEURL]" style="color: #9ca3af; text-decoration: underline;">[SITENAME]</a>. [LANG:COM_J2COMMERCE_EMAIL_ALL_RIGHTS_RESERVED]\n            </p>\n          </td>\n        </tr>\n\n      </table>\n    </td>\n  </tr>\n</table>\n','','visual','','','*',1,1),(2,'transactional','customer','7','*','*','[LANG:COM_J2COMMERCE_EMAIL_GOOD_NEWS_YOUR_ORDER_ITS_WAY]','<!-- J2Commerce Shipped Email — Modern Template -->\n<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: [EMAIL_BG_COLOR]; padding: 0; margin: 0;font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 20px 10px;">\n      <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%;background-color:#fff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td align="center" style="padding: 24px 40px; background-color: #ffffff; border-radiu